1	import React, { useState, useEffect } from "react";
2	import "./index.css";
3	import TierList from "./components/TierList";
4	import ImageHolder from "./components/ImageHolder";
5	import { AddTierButton } from "./components/TierModal";
6	import ProjectSelector from "./components/ProjectSelector";
7	import { migrateToProjectSystem } from "./utils/imageStore";
8	import { getProjectList, getCurrentProjectId, setCurrentProjectId, createProject } from "./utils/projectStore";
9	
10	interface Style {
11		ratio: string;
12		size: number;
13		quality: number;
14		pasteScaleMode: "fixed" | "preserve";
15	}
16	
17	interface StyleState {
18		style: Style;
19		setStyle: React.Dispatch<React.SetStateAction<Style>>;
20	}
21	
22	interface Tier {
23		id: number;
24		color: string;
25		tierLabel: string;
26	}
27	
28	interface TierState {
29		tiers: Tier[];
30		setTiers: React.Dispatch<React.SetStateAction<Tier[]>>;
31	}
32	
33	interface ProjectState {
34		projectId: string;
35		namespace: string;
36		switchProject: (newProjectId: string) => void;
37	}
38	
39	export const StylingContext = React.createContext<StyleState>({} as StyleState);
40	export const TierContext = React.createContext<TierState>({} as TierState);
41	export const ProjectContext = React.createContext<ProjectState>({} as ProjectState);
42	
43	interface AppInnerProps {
44		projectId: string;
45		namespace: string;
46		switchProject: (newProjectId: string) => void;
47	}
48	
49	const AppInner: React.FC<AppInnerProps> = ({ projectId, namespace, switchProject }) => {
50		const normalizeStyle = (value: unknown): Style => {
51			const fallback: Style = {
52				ratio: "preserve",
53				size: 80,
54				quality: 100,
55				pasteScaleMode: "preserve",
56			};
57	
58			if (typeof value !== "object" || value === null) {
59				return fallback;
60			}
61	
62			const styleValue = value as Partial<Style>;
63	
64			return {
65				ratio: typeof styleValue.ratio === "string" ? styleValue.ratio : fallback.ratio,
66				size: typeof styleValue.size === "number" ? styleValue.size : fallback.size,
67				quality: typeof styleValue.quality === "number" ? styleValue.quality : fallback.quality,
68				pasteScaleMode:
69					styleValue.pasteScaleMode === "preserve" || styleValue.pasteScaleMode === "fixed"
70						? styleValue.pasteScaleMode
71						: fallback.pasteScaleMode,
72			};
73		};
74	
75		const tiersKey = `${namespace}_tiers`;
76		const styleKey = `${namespace}_style`;
77	
78		const [style, setStyle] = useState<Style>(() => {
79			const storedStyle = localStorage.getItem(styleKey);
80			if (storedStyle) {
81				if (storedStyle.startsWith("{")) {
82					return normalizeStyle(JSON.parse(storedStyle));
83				} else {
84					// MIGRATION: OLD STYLE FORMAT
85					const ratio = storedStyle;
86					return { ratio: ratio, size: 80, quality: 100, pasteScaleMode: "preserve" };
87				}
88			} else {
89				return { ratio: "preserve", size: 80, quality: 100, pasteScaleMode: "preserve" };
90			}
91		});
92	
93		const [tiers, setTiers] = useState<Tier[]>(() => {
94			const storedTiers = localStorage.getItem(tiersKey);
95	
96			if (storedTiers) {
97				const parsedTiers: any[] = JSON.parse(storedTiers);
98	
99				// MIGRATION: ID USED TO REPRESENT TIER LABEL
100				// IDENTIFIER USED COMBINATION OF COLOR AND LABEL
101				// WE WILL MIMIC THE OLD BEHAVIOR FOR OLDER SAVES (OLD SAVES USE THIS FOR IMAGE LOOKUP)
102				// FUTURE SAVES WILL USE NEW FORMAT OF DATE.NOW()
103				// this is my first time writing migration code and writing comments about it :3
104				// if you see this DM me I'm convinced nobody will ever read this
105				const isOldFormat = parsedTiers.some((tier) => !("tierLabel" in tier));
106				if (isOldFormat) {
107					return parsedTiers.map((tier, index) => ({
108						color: tier.color,
109						tierLabel: tier.id,
110						id: `${tier.color}_${tier.id}`,
111					}));
112				} else {
113					return parsedTiers;
114				}
115			}
116	
117			return [
118				{ color: "#FF7F7F", tierLabel: "S", id: 1 },
119				{ color: "#FFBF7F", tierLabel: "A", id: 2 },
120				{ color: "#FFDF80", tierLabel: "B", id: 3 },
121				{ color: "#FFFF7F", tierLabel: "C", id: 4 },
122				{ color: "#BFFF7F", tierLabel: "D", id: 5 },
123			];
124		});
125	
126		useEffect(() => {
127			localStorage.setItem(tiersKey, JSON.stringify(tiers));
128		}, [tiers, tiersKey]);
129	
130		useEffect(() => {
131			localStorage.setItem(styleKey, JSON.stringify(style));
132		}, [style, styleKey]);
133	
134		return (
135			<ProjectContext.Provider value={{ projectId, namespace, switchProject }}>
136				<StylingContext.Provider value={{ style, setStyle }}>
137					<TierContext.Provider value={{ tiers, setTiers }}>
138						<div className="p-8 min-h-[100vh] bg-stone-800">
139							<ProjectSelector />
140							<TierList />
141							<AddTierButton />
142							<ImageHolder />
143						</div>
144					</TierContext.Provider>
145				</StylingContext.Provider>
146			</ProjectContext.Provider>
147		);
148	};
149	
150	const App = () => {
151		const [appState, setAppState] = useState<{ projectId: string; namespace: string } | null>(null);
152	
153		// Called from ProjectSelector via ProjectContext when user switches projects
154		const switchToProject = (newProjectId: string) => {
155			setCurrentProjectId(newProjectId);
156			setAppState({ projectId: newProjectId, namespace: `project_${newProjectId}` });
157		};
158	
159		useEffect(() => {
160			const init = async () => {
161				const DEFAULT_PROJECT_ID = "default";
162				const DEFAULT_NAMESPACE = `project_${DEFAULT_PROJECT_ID}`;
163	
164				// Check if project system already exists
165				const projectList = getProjectList();
166	
167				if (projectList.length === 0) {
168					// --- First-time migration: move old data into default project ---
169	
170					// Migrate localStorage keys
171					const oldTiers = localStorage.getItem("tiers");
172					const oldStyle = localStorage.getItem("style");
173	
174					if (oldTiers) {
175						localStorage.setItem(`${DEFAULT_NAMESPACE}_tiers`, oldTiers);
176					}
177					if (oldStyle) {
178						localStorage.setItem(`${DEFAULT_NAMESPACE}_style`, oldStyle);
179					}
180	
181					// Migrate IndexedDB images to namespaced keys
182					await migrateToProjectSystem(DEFAULT_NAMESPACE);
183	
184					// Create default project
185					createProject("Default");
186					setCurrentProjectId(DEFAULT_PROJECT_ID);
187	
188					// Clean up old un-namespaced localStorage keys
189					localStorage.removeItem("tiers");
190					localStorage.removeItem("style");
191				}
192	
193				const currentId = getCurrentProjectId() || DEFAULT_PROJECT_ID;
194				setAppState({ projectId: currentId, namespace: `project_${currentId}` });
195			};
196	
197			init();
198		}, []);
199	
200		if (!appState) {
201			return (
202				<div className="p-8 min-h-[100vh] bg-stone-800 flex items-center justify-center">
203					<p className="text-gray-400 text-lg">Loading...</p>
204				</div>
205			);
206		}
207	
208		return (
209			<AppInner
210				key={appState.projectId}
211				projectId={appState.projectId}
212				namespace={appState.namespace}
213				switchProject={switchToProject}
214			/>
215		);
216	};
217	
218	export default App;
219

1	import { useContext } from "react";
2	import Tier from "./Tier";
3	import { ReactSortable } from "react-sortablejs";
4	import { ProjectContext, TierContext } from "../App";
5	import { deleteImageStore } from "../utils/imageStore";
6	
7	const TierList = () => {
