1	import React, { useState, useEffect, useRef, useContext, useCallback } from "react";
2	import { ReactSortable } from "react-sortablejs";
3	import { SketchPicker } from "react-color";
4	import { ProjectContext, StylingContext, TierContext } from "../App"
5	import Image from "./Image"
6	import {
7		getImageStore,
8		migrateImageStoresFromLocalStorage,
9		deleteOriginalImageData,
10		setImageStore,
11		getFullResolutionImages,
12		resizeStoredImages,
13	} from "../utils/imageStore";
14	
15	interface ImageItem {
16		id: number;
17		url: string;
18		text?: string;
19	}
20	
21	interface TierProps {
22		id: number;
23		color: string;
24		tierLabel: string;
25		onDelete: () => void;
26	}
27	
28	const Tier: React.FC<TierProps> = ({ id, color, tierLabel, onDelete }) => {
29		const { namespace } = useContext(ProjectContext);
30		const { style } = useContext(StylingContext);
31	
32		const [images, setImages] = useState<ImageItem[]>([]);
33		const [hasHydratedImages, setHasHydratedImages] = useState(false);
34		const [previewPixelSize, setPreviewPixelSize] = useState(() =>
35			Math.max(1, Math.round(style.size * (window.devicePixelRatio || 1)))
36		);
37		const isPreviewRefreshRef = useRef(false);
38	
39		const [isContextMenuOpen, setIsContextMenuOpen] = useState(false);
40		const [contextMenuPosition, setContextMenuPosition] = useState({
41			left: 0,
42			top: 0
43		});
44	
45		const { tiers, setTiers } = useContext(TierContext) || {};
46		
47		const contextMenuRef = useRef<HTMLDivElement>(null);
48	
49		const getPreviewPixelSize = useCallback(
50			() => Math.max(1, Math.round(style.size * (window.devicePixelRatio || 1))),
51			[style.size]
52		);
53	
54		useEffect(() => {
55			let debounceHandle: number | undefined;
56	
57			const schedulePreviewRefresh = () => {
58				if (debounceHandle !== undefined) {
59					window.clearTimeout(debounceHandle);
60				}
61	
62				debounceHandle = window.setTimeout(() => {
63					setPreviewPixelSize((currentValue) => {
64						const nextValue = getPreviewPixelSize();
65						if (currentValue === nextValue) {
66							isPreviewRefreshRef.current = false;
67							return currentValue;
68						}
69						isPreviewRefreshRef.current = true;
70						return nextValue;
71					});
72				}, 150);
73			};
74	
75			setPreviewPixelSize(getPreviewPixelSize());
76			window.addEventListener("resize", schedulePreviewRefresh);
77			window.addEventListener("scroll", schedulePreviewRefresh, { passive: true });
78			window.visualViewport?.addEventListener("resize", schedulePreviewRefresh);
79			window.visualViewport?.addEventListener("scroll", schedulePreviewRefresh, { passive: true });
80	
81			return () => {
82				if (debounceHandle !== undefined) {
83					window.clearTimeout(debounceHandle);
84				}
85	
86				window.removeEventListener("resize", schedulePreviewRefresh);
87				window.removeEventListener("scroll", schedulePreviewRefresh);
88				window.visualViewport?.removeEventListener("resize", schedulePreviewRefresh);
89				window.visualViewport?.removeEventListener("scroll", schedulePreviewRefresh);
90			};
91		}, [getPreviewPixelSize]);
92	
93		const tierIndex = tiers.findIndex((tier) => tier.color === color && tier.tierLabel === tierLabel);
94		const editedColor = tierIndex !== -1 ? tiers[tierIndex].color : color;
95		const editedTierLabel = tierIndex !== -1 ? tiers[tierIndex].tierLabel : tierLabel;
96	
97		useEffect(() => {
98			const handleOutsideClick = (e: MouseEvent) => {
99				if (
100					isContextMenuOpen &&
101					contextMenuRef.current &&
102					!contextMenuRef.current.contains(e.target as Node)
103				) {
104					handleCloseContextMenu();
105				}
106			};
107	
108			window.addEventListener("click", handleOutsideClick);
109	
110			return () => {
111				window.removeEventListener("click", handleOutsideClick);
112			};
113		}, [isContextMenuOpen]);
114	
115		useEffect(() => {
116			let isMounted = true;
117	
118			const loadImages = async () => {
119				await migrateImageStoresFromLocalStorage(namespace);
120				const storedImages = await getImageStore(namespace, `tierImages_${id}`);
121				const resizedImages = await resizeStoredImages(namespace, storedImages, {
122					size: previewPixelSize,
123					quality: style.quality,
124					pasteScaleMode: style.pasteScaleMode,
125				});
126				if (isMounted) {
127					isPreviewRefreshRef.current = false;
128					setImages(resizedImages);
129					setHasHydratedImages(true);
130				}
131			};
132	
133			loadImages();
134	
135			return () => {
136				isMounted = false;
137			};
138		}, [id, previewPixelSize, style.pasteScaleMode, style.quality, style.size]);
139	
140		useEffect(() => {
141			if (!hasHydratedImages) {
142				return;
143			}
144	
145			if (isPreviewRefreshRef.current) {
146				isPreviewRefreshRef.current = false;
147				return;
148			}
149	
150			const persistImages = async () => {
151				const fullResolutionImages = await getFullResolutionImages(namespace, images);
152				await setImageStore(namespace, `tierImages_${id}`, fullResolutionImages);
153			};
154	
155			persistImages();
156		}, [images, id, hasHydratedImages]);
157	
158		const handleColorChange = (newColor: any) => {
159			if (tierIndex !== -1) {
160				const updatedTiers = [...tiers];
161				updatedTiers[tierIndex].color = newColor.hex;
162				setTiers(updatedTiers);
163			}
164		};
165	
166		const handleTierLabelChange = (event: React.ChangeEvent<HTMLInputElement>) => {
167			if (tierIndex !== -1) {
168				const updatedTiers = [...tiers];
169				updatedTiers[tierIndex].tierLabel = event.target.value;
170				setTiers(updatedTiers);
171			}
172		};
173	
174		const handleContextMenu = (e: React.MouseEvent<HTMLDivElement>) => {
175			e.preventDefault();
176			setIsContextMenuOpen(true);
177			setContextMenuPosition({ left: e.clientX, top: e.clientY });
178		};
179	
180		const handleCloseContextMenu = () => {
181			setIsContextMenuOpen(false);
182		};
183	
184		const handleDeleteImage = useCallback((imageId: number) => {
185			deleteOriginalImageData(namespace, imageId).catch((error) => {
186				console.error("Failed to delete original image data:", error);
187			});
188			setImages((prevImages) => prevImages.filter((img) => img.id !== imageId));
189		}, []);
190	
191		const handleEditImageText = useCallback((imageId: number, nextText: string) => {
192			setImages((prevImages) =>
193				prevImages.map((img) => (img.id === imageId ? { ...img, text: nextText } : img))
194			);
195		}, []);
196	
197		const handleDeleteTier = async () => {
198			await Promise.all(images.map((image) => deleteOriginalImageData(namespace, image.id).catch((error) => {
199				console.error("Failed to delete original image data:", error);
200			})));
201			onDelete();
202			handleCloseContextMenu();
203		};
204	
205		const calculateContextMenuPosition = () => {
206			// Too lazy to call re-render, so hardcoded since these values won't change, crucify me
207			// Lol what the fuck is this guy above me talking avbout
208			const menuWidth = contextMenuRef.current?.offsetWidth || 236;
209			const menuHeight = contextMenuRef.current?.offsetHeight || 402;
210			let left = contextMenuPosition.left;
211			let top = contextMenuPosition.top;
212			if (left + menuWidth > window.innerWidth) {
213				left = window.innerWidth - menuWidth - 10;
214			}
215			if (top + menuHeight > window.innerHeight) {
216				top = window.innerHeight - menuHeight - 10;
217			}
218			return { left, top };
219		};
220	
221		return (
222			<div className="flex bg-[#1A1A17] gap-[2px]">
223				<div
224					onContextMenu={handleContextMenu}
225					className={`w-24 flex justify-center items-center handle cursor-move`}
226					style={{ backgroundColor: editedColor, minHeight: `${style.size}px`, width: `${style.size*1.2}px`, fontSize: `${style.size/5}px` }}
227				>
228					<p className="text-center" style={{ overflowWrap: "anywhere" }}>
229						{editedTierLabel}
230					</p>
231				</div>
232				<ReactSortable
233					list={images}
234					setList={setImages}
235					tag="div"
236					group="shared"
237					className="react-sortablejs flex space-x-[2px] flex-1 flex-wrap"
238				>
239					{images.map((image) => (
240						<Image
241							key={image.id}
242							imageId={image.id}
243							imageUrl={image.url}
244							imageText={image.text}
245							onDelete={handleDeleteImage}
246							onEditText={handleEditImageText}
247						/>
248					))}
249				</ReactSortable>
250	
251				{isContextMenuOpen && (
252					<div
253						ref={contextMenuRef}
254						className="fixed bg-zinc-800 text-white p-2 rounded-md shadow-2xl z-10"
255						style={{
256							...calculateContextMenuPosition(),
257						}}
258						id="context-menu"
259					>
260						<div>
261							<label className="block text-gray-300 font-semibold">
262								Edit Color
263							</label>
264							<SketchPicker
265								color={editedColor}
266								onChange={handleColorChange}
267								disableAlpha
268								presetColors={[
269									"#FF7F7F",
270									"#FFBF7F",
271									"#FFDF80",
272									"#FFFF7F",
273									"#BFFF7F",
274									"#7FFF7F"
275								]}
276								className="text-black"
277							/>
278						</div>
279						<div>
280							<label className="block text-gray-300 font-semibold">
281								Edit Name
282							</label>
283							<input
284								type="text"
285								placeholder="Tier Label"
286								className="mt-1 p-2 w-full border rounded-md focus:ring focus:ring-indigo-300 text-black"
287								value={editedTierLabel}
288								onChange={handleTierLabelChange}
289							/>
290						</div>
291						<div>
292							<span
293								className="text-red-500 cursor-pointer"
294								onClick={handleDeleteTier}
295							>
296								Delete Tier
297							</span>
298						</div>
299					</div>
300				)}
301			</div>
302		);
303	};
304	
305	export default Tier;
306

1	import React, { useState, ChangeEvent, FormEvent, useContext } from "react";
2	import { SketchPicker } from "react-color";
3	import { StylingContext, TierContext } from "../App";
4	
5	interface ModalProps {
6		isOpen: boolean;
7		onClose: () => void;
8		onAddTier: (color: string, tierLabel: string) => void;
9	}
10	
11	export const AddTierButton: React.FC = () => {
12		const { style } = useContext(StylingContext);
13		const { setTiers } = useContext(TierContext);
14		
15		const [isModalOpen, setIsModalOpen] = useState(false);
16	
17		const openModal = () => {
18			setIsModalOpen(true);
19		};
20	
21		const closeModal = () => {
22			setIsModalOpen(false);
23		};
24	
25		const addTier = (color: string, tierLabel: string) => {
26			const newTier = { color: color || "#ffffff", tierLabel: tierLabel || "New Tier", id: Date.now() };
27			setTiers((prevTiers) => [...prevTiers, newTier]);
28		};
29	
30		return (
31			<>
32				<button onClick={openModal} className="bg-stone-600 hover:bg-stone-700 text-white font-semibold py-2 px-4 my-4" style={{width: style.size * 1.2}}>
33					Add Tier
34				</button>
35				<TierModal
36					isOpen={isModalOpen}
37					onClose={closeModal}
38					onAddTier={addTier}
39				/>
40			</>
41		)
42	}
43	
44	export const TierModal: React.FC<ModalProps> = ({ isOpen, onClose, onAddTier }) => {
45		const [tierLabel, setTierLabel] = useState("");
46		const [color, setColor] = useState("");
47	
48		const handleTierLabelChange = (event: ChangeEvent<HTMLInputElement>) => {
49			setTierLabel(event.target.value);
50		};
51	
52		const handleColorChange = (newColor: any) => {
53			setColor(newColor.hex);
54		};
55	
56		const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
57			event.preventDefault();
58			onAddTier(color, tierLabel);
59			onClose();
60		};
61	
62		const handleClick = (event: React.MouseEvent<HTMLDivElement>) => {
63			const target = event.target as HTMLElement;
64			if (target.id === "modal-bg") onClose();
65		};
66	
67		if (!isOpen) {
68			return null;
69		}
70	
71		return (
72			<div
73				className="fixed inset-0 flex items-center justify-center z-50 bg-black bg-opacity-50 dark:bg-opacity-70"
74				id="modal-bg"
75				onMouseDown={handleClick}
76			>
77				<div className="bg-zinc-800 p-6 rounded-md shadow-md">
78					<h2 className="text-lg font-semibold mb-4 text-white">New Tier</h2>
79					<form autoComplete="false" onSubmit={handleSubmit}>
80						<div className="mb-4">
81							<label
82								htmlFor="tierLabel"
83								className="block text-sm font-medium text-gray-300"
84							>
85								Tier Label
86							</label>
87							<input
88								type="text"
89								placeholder="Tier Label"
90								id="tierLabel"
91								className="mt-1 p-2 w-full border rounded-md focus:ring focus:ring-indigo-300 text-black"
92								value={tierLabel}
93								onChange={handleTierLabelChange}
