63		return new Promise<T>((resolve, reject) => {
64			const transaction = db.transaction(IMAGE_STORE, mode);
65			const store = transaction.objectStore(IMAGE_STORE);
66			const request = handler(store);
67	
68			request.onsuccess = () => resolve(request.result);
69			request.onerror = () => reject(request.error);
70		});
