129	const compressAndDownscaleImage = (
130		base64: string,
131		maxHeight: number,
132		qualityPercent: number,
133		shouldScale: boolean,
134	): Promise<string> => {
135		return new Promise((resolve) => {
136			const img = document.createElement("img");
137			img.onload = () => {
138				const canvas = document.createElement("canvas");
139				const ctx = canvas.getContext("2d");
140				if (!ctx || img.naturalWidth === 0 || img.naturalHeight === 0) {
141					resolve(base64);
142					return;
143				}
144	
145				const scale = shouldScale ? maxHeight / img.naturalHeight : Math.min(1, maxHeight / img.naturalHeight);
146				canvas.width = Math.max(1, Math.round(img.naturalWidth * scale));
147				canvas.height = Math.max(1, Math.round(img.naturalHeight * scale));
148				ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
149				const output = canvas.toDataURL("image/jpeg", qualityPercent / 100);
150				resolve(output);
151			};
152			img.onerror = () => {
153				resolve(base64);
154			};
155			img.src = base64;
156		});
157	};
