248	export const migrateImageStoresFromLocalStorage = async (namespace: string): Promise<void> => {
249		if (migrationPromise) {
250			return migrationPromise;
251		}
252	
253		migrationPromise = (async () => {
254			if (localStorage.getItem(MIGRATION_FLAG) === "true") {
255				return;
256			}
257	
258			const keysToMigrate = [
259				IMAGE_HOLDER_KEY,
260				...getTierImageKeysFromLocalStorage(),
261			];
262	
263			for (const key of keysToMigrate) {
264				const parsedImages = parseStoredImages(localStorage.getItem(key));
265				if (parsedImages.length > 0) {
266					await setImageStore(namespace, key, parsedImages);
267					await Promise.all(
268						parsedImages.map((image) =>
269							setOriginalImageData(namespace, {
270								id: image.id,
271								url: image.url,
272							})
273						)
274					);
275				}
