288	/**
289	 * One-time migration from un-namespaced IndexedDB keys to project-namespaced keys.
290	 * This copies all existing keys without "project_" prefix into the given namespace.
291	 */
292	const migrateIndexedDBToNamespace = async (namespace: string): Promise<void> => {
293		const allKeys = await getAllStoreKeys();
294	
295		for (const key of allKeys) {
296			// Skip keys that are already namespaced
297			if (key.startsWith("project_")) continue;
298	
299			const value = await withStore("readonly", (store) => store.get(key));
300			if (value !== undefined) {
301				await withStore("readwrite", (store) => store.put(value, nsKey(namespace, key)));
302			}
303		}
304	};
