306	/**
307	 * Full migration to the v2 project system.
308	 * - Migrates localStorage images to namespaced IndexedDB (if v1 not done)
309	 * - Copies existing un-namespaced IndexedDB keys to the default namespace
310	 * Returns the default namespace string.
311	 */
312	export const migrateToProjectSystem = async (namespace: string): Promise<void> => {
313		if (localStorage.getItem(V2_MIGRATION_FLAG) === "true") {
314			return;
315		}
316	
317		// Step 1: Ensure v1 migration is done (localStorage images → IndexedDB)
318		const v1Done = localStorage.getItem(MIGRATION_FLAG) === "true";
319	
320		if (!v1Done) {
321			const keysToMigrate = [
322				IMAGE_HOLDER_KEY,
323				...getTierImageKeysFromLocalStorage(),
324			];
325	
326			for (const key of keysToMigrate) {
327				const parsedImages = parseStoredImages(localStorage.getItem(key));
328				if (parsedImages.length > 0) {
329					await setImageStore(namespace, key, parsedImages);
330					await Promise.all(
331						parsedImages.map((image) =>
332							setOriginalImageData(namespace, {
333								id: image.id,
334								url: image.url,
335							})
336						)
337					);
338				}
339	
340				if (localStorage.getItem(key) !== null) {
341					localStorage.removeItem(key);
342				}
343			}
344	
345			localStorage.setItem(MIGRATION_FLAG, "true");
346		}
347	
348		// Step 2: Copy un-namespaced IndexedDB keys to namespaced versions
349		await migrateIndexedDBToNamespace(namespace);
350	
351		localStorage.setItem(V2_MIGRATION_FLAG, "true");
352	};
