224		const imageCellHeightPx = imageSizePx + cellPaddingPx * 2;
225	
226		const maxImageCount = options.maxEmbeddedImageCount ?? DEFAULT_EMBEDDED_IMAGE_COUNT_LIMIT;
227		const maxImageBytes = options.maxEmbeddedImageBytes ?? DEFAULT_EMBEDDED_IMAGE_BYTES_LIMIT;
228		const totalImageBytes = manifest.reduce((sum, item) => {
229			const { base64Data } = splitDataUrl(item.dataUrl);
230			return sum + estimateBase64SizeBytes(base64Data);
231		}, 0);
232	
233		let canEmbedImages = options.embedImages;
234		let reason: string | undefined;
235	
236		if (manifest.length > maxImageCount) {
237			canEmbedImages = false;
238			reason = `Embedded images disabled: ${manifest.length} images exceeds limit of ${maxImageCount}.`;
239		}
240	
241		if (totalImageBytes > maxImageBytes) {
242			canEmbedImages = false;
243			reason = `Embedded images disabled: estimated ${Math.round(totalImageBytes / (1024 * 1024))}MB exceeds limit of ${Math.round(maxImageBytes / (1024 * 1024))}MB.`;
244		}
245	
246		const tierRowsMap = new Map<string, { label: string; color: string; tierOrder: number; images: ExportManifestEntry[] }>();
247	
248		for (const item of manifest) {
249			const key = `${item.tierOrder}:${item.tierLabel}`;
250			const existing = tierRowsMap.get(key);
251			if (existing) {
252				existing.images.push(item);
253			} else {
254				tierRowsMap.set(key, {
255					label: item.tierLabel,
256					color: item.tierColor,
257					tierOrder: item.tierOrder,
258					images: [item],
259				});
260			}
261		}
262	
263		const tierRows = Array.from(tierRowsMap.values()).sort((a, b) => a.tierOrder - b.tierOrder);
264		const maxImagesInTier = Math.max(...tierRows.map((row) => row.images.length), 0);
265	
266		sheet.getColumn(1).width = 18;
267		for (let colIndex = 0; colIndex < maxImagesInTier; colIndex += 1) {
268			sheet.getColumn(colIndex + 2).width = pxToExcelColumnWidth(imageCellWidthPx);
269		}
270	
271		for (const tierRow of tierRows) {
272			const rowValues = [tierRow.label, ...Array(maxImagesInTier).fill("")];
273			const row = sheet.addRow(rowValues);
274			row.height = pxToPoints(imageCellHeightPx);
275	
276			const tierCell = sheet.getCell(row.number, 1);
277			tierCell.fill = {
278				type: "pattern",
279				pattern: "solid",
280				fgColor: { argb: hexToArgb(tierRow.color) },
281			};
282			tierCell.alignment = {
283				vertical: "middle",
284				horizontal: "center",
285			};
286	
287			if (!canEmbedImages) {
288				for (let imageIndex = 0; imageIndex < tierRow.images.length; imageIndex += 1) {
289					const cell = sheet.getCell(row.number, imageIndex + 2);
290					cell.value = tierRow.images[imageIndex].filename;
291					cell.alignment = {
292						vertical: "middle",
293						horizontal: "center",
294					};
295				}
296				continue;
297			}
298	
299			for (let imageIndex = 0; imageIndex < tierRow.images.length; imageIndex += 1) {
300				const entry = tierRow.images[imageIndex];
301				const { base64Data, mimeType } = splitDataUrl(entry.dataUrl);
302				const extension = mimeTypeToExtension(mimeType);
303	
304				if (extension === "jpg" || extension === "png" || extension === "gif") {
305					const excelExtension = extension === "jpg" ? "jpeg" : extension;
306					const imageId = workbook.addImage({
307						base64: entry.dataUrl,
308						extension: excelExtension,
309					});
310	
311					const dimensions = await getDataUrlDimensions(entry.dataUrl);
312					const placed = getPlacedSize(dimensions.width, dimensions.height, imageSizePx, ratioMode);
313					const offsetX = Math.max(0, Math.floor((imageCellWidthPx - placed.width) / 2));
314					const offsetY = Math.max(0, Math.floor((imageCellHeightPx - placed.height) / 2));
315	
316					sheet.addImage(imageId, {
317						tl: {
318							col: imageIndex + 1 + offsetX / imageCellWidthPx,
319							row: row.number - 1 + offsetY / imageCellHeightPx,
320						},
321						ext: { width: placed.width, height: placed.height },
322						editAs: "oneCell",
323					});
324				} else if (base64Data) {
325					const cell = sheet.getCell(row.number, imageIndex + 2);
326					cell.value = entry.filename;
327					cell.alignment = {
328						vertical: "middle",
329						horizontal: "center",
330					};
331				}
332			}
333		}
334	
335		if (!canEmbedImages) {
336			const noteSheet = workbook.addWorksheet("Notes");
337			noteSheet.getCell("A1").value = reason ?? "Embedded images disabled by limits.";
338		}
339	
340		const workbookBytes = await workbook.xlsx.writeBuffer();
341		return {
342			workbookBytes: workbookBytes instanceof Uint8Array ? workbookBytes : new Uint8Array(workbookBytes),
343			usedEmbeddedSpreadsheet: canEmbedImages,
344			reason,
345		};
346	};
