348	export const collectFullResolutionManifest = async (
349		namespace: string,
350		tiers: TierItem[] | undefined,
351	): Promise<ExportManifestEntry[]> => {
352		const safeTiers = Array.isArray(tiers) ? tiers : [];
353		const manifest: ExportManifestEntry[] = [];
354		let globalOrder = 1;
355	
356		for (let tierIndex = 0; tierIndex < safeTiers.length; tierIndex += 1) {
357			const tier = safeTiers[tierIndex];
358			const tierLabel = typeof tier.tierLabel === "string" ? tier.tierLabel : "";
359			const tierFolder = sanitizeFolderName(tierLabel || `tier_${tierIndex + 1}`);
360			const tierImages = await getImageStore(namespace, `tierImages_${tier.id}`) as StoredImage[];
361	
362			for (let itemIndex = 0; itemIndex < tierImages.length; itemIndex += 1) {
363				const image = tierImages[itemIndex];
364				const originalData = await getOriginalImageData(namespace, image.id);
365				const dataUrl = originalData ?? image.url;
366				const { mimeType } = splitDataUrl(dataUrl);
367				const extension = mimeTypeToExtension(mimeType);
368				const filename = `${padIndex(itemIndex + 1)}.${extension}`;
369				manifest.push({
370					group: "tier",
371					folder: tierFolder,
372					tierLabel,
373					tierColor: normalizeHexColor(tier.color ?? DEFAULT_TIER_COLOR),
374					tierOrder: tierIndex + 1,
375					itemOrder: itemIndex + 1,
376					globalOrder,
377					imageId: image.id,
378					filename,
379					relativePath: `tiers/${tierFolder}/${filename}`,
380					mimeType,
381					text: image.text ?? "",
382					dataUrl,
383				});
384				globalOrder += 1;
385			}
386		}
387	
388		const unassignedImages = await getImageStore(namespace, "imageHolder") as StoredImage[];
389		for (let itemIndex = 0; itemIndex < unassignedImages.length; itemIndex += 1) {
390			const image = unassignedImages[itemIndex];
391			const originalData = await getOriginalImageData(namespace, image.id);
392			const dataUrl = originalData ?? image.url;
393			const { mimeType } = splitDataUrl(dataUrl);
394			const extension = mimeTypeToExtension(mimeType);
395			const filename = `${padIndex(itemIndex + 1)}.${extension}`;
396			manifest.push({
397				group: "unassigned",
398				folder: "unassigned",
399				tierLabel: "unassigned",
400				tierColor: DEFAULT_TIER_COLOR,
401				tierOrder: safeTiers.length + 1,
402				itemOrder: itemIndex + 1,
403				globalOrder,
404				imageId: image.id,
405				filename,
406				relativePath: `unassigned/${filename}`,
407				mimeType,
408				text: image.text ?? "",
409				dataUrl,
410			});
411			globalOrder += 1;
412		}
413	
414		return manifest;
415	};
