417	export const buildExportZip = async (
418		manifest: ExportManifestEntry[],
419	): Promise<{ zipBlob: Blob }> => {
420		const zip = new JSZip();
421	
422		for (const entry of manifest) {
423			const { base64Data } = splitDataUrl(entry.dataUrl);
424			if (base64Data) {
425				zip.file(entry.relativePath, base64Data, { base64: true });
426			}
427		}
428	
429		zip.file("manifest.json", JSON.stringify(manifest.map(({ dataUrl, ...rest }) => rest), null, 2));
430		zip.file("manifest.csv", buildCsv(manifest));
431	
432		const zipBlob = await zip.generateAsync({ type: "blob" });
433		return { zipBlob };
434	};
