436	export const buildSpreadsheetExport = async (
437		manifest: ExportManifestEntry[],
438		spreadsheetOptions: SpreadsheetOptions,
439	): Promise<{ spreadsheetBlob: Blob; usedEmbeddedSpreadsheet: boolean; spreadsheetReason?: string }> => {
440		const spreadsheet = await buildTierSpreadsheet(manifest, spreadsheetOptions);
441		const normalizedBytes = Uint8Array.from(spreadsheet.workbookBytes);
442		const spreadsheetBlob = new Blob([normalizedBytes], {
443			type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
444		});
445	
446		return {
447			spreadsheetBlob,
448			usedEmbeddedSpreadsheet: spreadsheet.usedEmbeddedSpreadsheet,
449			spreadsheetReason: spreadsheet.reason,
450		};
451	};
